corrected_code:
namespace App\Livewire;

use Livewire\Component;
use App\Models\SupportTicketAttachment;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Facades\Auth;

class TicketAttachmentManager extends Component
{
    public int $attachmentId;

    public function deleteAttachment()
    {
        $attachment = SupportTicketAttachment::findOrFail($this->attachmentId);
        $this->authorize('delete', $attachment);

        Storage::disk('support_docs')->delete($attachment->file_path);
        $attachment->delete();
    }

    public function render()
    {
        return view('livewire.ticket-attachment-manager');
    }
}
